import re
import os

def convert_java_to_ts(input_file, output_file):
    # Regex to match: public static final String KEY = "value";
    pattern = re.compile(r'public\s+static\s+final\s+String\s+(\w+)\s+=\s+"([^"]+)";')

    ts_lines = [
        "/**",
        " * Generated from ErrorCode.java",
        " * Do not edit this file manually",
        " */",
        "",
        "export const ErrorCode = {",
    ]

    try:
        # Create output directory if it doesn't exist
        output_dir = os.path.dirname(output_file)
        if output_dir and not os.path.exists(output_dir):
            os.makedirs(output_dir)
            print(f"📁 Created directory: {output_dir}")

        with open(input_file, 'r', encoding='utf-8') as f:
            content = f.readlines()

        found_any = False
        for line in content:
            match = pattern.search(line)
            if match:
                found_any = True
                var_name = match.group(1)
                value = match.group(2)
                ts_lines.append(f'    {var_name}: "{value}",')

        if not found_any:
            print("⚠️ Warning: No ErrorCodes were found in the Java file. Check your regex or file content.")
            return

        # Remove the trailing comma from the last element
        if ts_lines[-1].endswith(','):
            ts_lines[-1] = ts_lines[-1][:-1]

        ts_lines.append("} as const;")
        ts_lines.append("")
        ts_lines.append("export type ErrorCodeType = typeof ErrorCode[keyof typeof ErrorCode];")

        with open(output_file, 'w', encoding='utf-8') as f:
            f.write("\n".join(ts_lines))

        print(f"✅ Successfully converted:\n   From: {input_file}\n   To: {output_file}")

    except FileNotFoundError:
        print(f"❌ Error: The source file was not found at {input_file}")
    except Exception as e:
        print(f"❌ An error occurred: {str(e)}")

if __name__ == "__main__":
    # Using 'r' prefix for Raw Strings to handle Windows backslashes correctly
    input_path = r"D:\Projects\split-smart\backend\gateway\src\main\java\com\onewordmax\splitsmart\gateway\constants\ErrorCode.java"
    output_path = r"D:\Learning\React-Native\youtube-freecodecamp\my-app\src\api\dto\defaults\gateway\ErrorCode.ts"

    convert_java_to_ts(input_path, output_path)